package server

import "html/template"

func portalLayoutClass(files, users, chat bool) string {
	if chat {
		files = false
	}
	switch {
	case files && users && chat:
		return "layout-files-users-chat"
	case files && chat:
		return "layout-files-chat"
	case users && chat:
		return "layout-users-chat"
	case files:
		return "layout-single"
	case chat:
		return "layout-single"
	default:
		return "layout-empty"
	}
}

